#include <iostream>

struct Animal { virtual ~Animal() = default; };
struct Cat : Animal {};
struct Dog : Animal {};

int main() {
  Cat cat;
  Dog dog;
  Animal* first = &cat;
  Animal* second = &dog;
  std::cout << (dynamic_cast<Dog*>(first) != nullptr)
            << (dynamic_cast<Dog*>(second) != nullptr);
}
